        c_indices = []
        for r in range(len(grid)):
            for col_idx, val in enumerate(grid[r]):
                if val == c:
                    r_indices.append(r)
                    c_indices.append(col_idx)

        if r_indices and c_indices:
            rm, rM = min(r_indices), max(r_indices)
            cm, cM = min(c_indices), max(c_indices)

            # Check all four corners of bounding box
            if grid[rm][cm] == c and grid[rm][cM] == c and grid[rM][cm] == c and grid[rM][cM] == c:
                frame_color = c
                r_min, r_max, c_min, c_max = rm, rM, cm, cM
                break

    if frame_color is None:
        return grid

    # Output grid dimensions
    h = r_max - r_min + 1
    w = c_max - c_min + 1

    out_grid = [[0] * w for _ in range(h)]

    # Separate pixels and store values
    other_pixels = []
    frame_pixels = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != 0:
                if val == frame_color:
                    frame_pixels.append((r, c, val))
                else:
                    other_pixels.append((r, c, val))

    # Map other pixels
    for r, c, val in other_pixels:
        nr = (r - r_min) % h
        nc = (c - c_min) % w
        out_grid[nr][nc] = val

    # Map frame pixels (last, to preserve corners)
    for r, c, val in frame_pixels:
        nr = (r - r_min) % h
        nc = (c - c_min) % w
        out_grid[nr][nc] = val

    return out_grid
