def transform(grid):
    from collections import Counter

    # Identify background color (most frequent)
    counts = Counter()
    for row in grid:
        for val in row:
            counts[val] += 1
    bg = max(counts, key=counts.get)

    # Find all colors that form a perfect rectangular frame (corners present)
    candidates = []

    for c, _ in counts.items():
        if c == bg:
            continue

        rows, cols = set(), set()
        for r, row in enumerate(grid):
            for idx, val in enumerate(row):
                if val == c:
                    rows.add(r)
                    cols.add(idx)

        if not rows or not cols:
            continue

        r0, rM = min(rows), max(rows)
        c0, cM = min(cols), max(cols)

        # Check if all corners of the bounding box are the color c
        if (grid[r0][c0] == c and grid[r0][cM] == c and 
            grid[rM][c0] == c and grid[rM][cM] == c):

            h = rM - r0 + 1
            w = cM - c0 + 1
            candidates.append((h, w, c, r0, c0))

    # Select candidate with the largest area (heuristic for "Frame")
    candidates.sort(key=lambda x: x[0] * x[1], reverse=True)

    if not candidates:
        return grid

    best_h, best_w, frame_color, r_min, c_min = candidates[0]

    out = [[bg for _ in range(best_w)] for _ in range(best_h)]

    # Collect all non-background pixels
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != bg:
                # Map relative to frame top-left
                nr = (r - r_min) % best_h
                nc = (c - c_min) % best_w
                out[nr][nc] = val

    # Process frame pixels LAST to ensure corners (or overwrite)
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == frame_color:
                nr = (r - r_min) % best_h
                nc = (c - c_min) % best_w
                out[nr][nc] = val

    return out
